import type { ComponentProps } from 'react';

import Input from '@platform-ui/input';

import { createFormFieldAdapter } from './createAdapter';

export const FormField = createFormFieldAdapter<string, ComponentProps<typeof Input>>(
    ({ onChange, onBlur, onClean, value, ...props }) => {
        const handleBlur = () => {
            onChange(value?.trim());
            onBlur?.();
        };

        const handleClean = () => {
            onChange('');
            // @ts-expect-error хочет аргументы в onClean, я хочу выполнить коллбэк из пропсов (кейс: вызвать экшен на событие очистки)
            onClean?.();
        };

        return (
            <Input
                {...props}
                value={value}
                onChange={(e) => e && onChange(e.currentTarget.value)}
                onBlur={handleBlur}
                onClean={handleClean}
                ellipsis
                type="text"
            />
        );
    },
);
