import type { FieldError, Path } from 'react-hook-form';
import { useFormContext, useFormState } from 'react-hook-form';
import type { CheckoutFormInternalState, CheckoutFormState } from './Checkout';

export const CUSTOM_ERRORS_FIELD = '__custom_errors__';


