export const useFieldCustomError = (name: Path<CheckoutFormState>) => {
    const { errors: customErrors } = useFormState<CheckoutFormInternalState>({
        name: `${CUSTOM_ERRORS_FIELD}.${name}`,
    });

    const namePath = useMemo(() => name.split('.'), [name]);

    // @ts-ignore
    return path(namePath, customErrors?.[CUSTOM_ERRORS_FIELD]) as FieldError | undefined;
};

/**
 * Хук для простановки disabled состояния полям формы чекаута при отправки запроса на создание таски
 * disabled не проставляется полям данных карты и промокоду
 */
export const useIsFormFieldDisabled = (name?: Path<CheckoutFormState>) => {
    return false;
};

export const useClearCustomError = (name: Path<CheckoutFormState>) => {
    const { clearErrors } = useFormContext<CheckoutFormInternalState>();
    // const context = useConsumerContext();

    return useMemo(() => {
        return () => {
            // context.dispatch(resetCustomError(name));
            clearErrors(`${CUSTOM_ERRORS_FIELD}.${name}`);
        };
    }, [name]);
};
