import { ButtonMobile } from "@tui-react/button";
import "./App.css";
import { FormFieldTranslit } from "./FormFieldTranslit";
import { FormProvider, useForm } from "react-hook-form";
import { CheckoutFormState } from "./Checkout";
import { FormField } from "./FormField";

const MAX_LENGTH_32 = {
  maxLength: { value: 32, message: "Максимальная длина поля 32 символа" },
};
const REQUIRED_FIRST_NAME_RULE = {
  required: { value: true, message: "Заполните имя гостя" },
};
const REQUIRED_LAST_NAME_RULE = {
  required: { value: true, message: "Заполните фамилию гостя" },
};

function App() {
  const onBlurAnalyticsHandlerFirstName = () => {};
  const onBlurAnalyticsHandlerLastName = () => {};
  const form = useForm<CheckoutFormState>({
    defaultValues: {},
    mode: "onBlur",
  });

  return (
    <FormProvider {...form}>
      <div className="App">
        <div className="joe">
          <FormField
            cleanable
            rules={{ ...REQUIRED_FIRST_NAME_RULE, ...MAX_LENGTH_32 }}
            label="Имя"
            name="majorGuest.firstName"
            key="majorGuest.firstName"
            dataQaType="majorFirstNameInput"
            onBlur={onBlurAnalyticsHandlerFirstName}
          />
        </div>
        <div className="pass">
          <FormField
            cleanable
            rules={{ ...REQUIRED_LAST_NAME_RULE, ...MAX_LENGTH_32 }}
            label="Фамилия"
            name="majorGuest.lastName"
            key="majorGuest.lastName"
            dataQaType="majorLastNameInput"
            onBlur={onBlurAnalyticsHandlerLastName}
          />
        </div>
      </div>
    </FormProvider>
  );
}

export default App;
