import type { ComponentType } from 'react';

import { FormRow } from '@platform-ui/form';
import type { Path, UseControllerProps } from 'react-hook-form';
import { useController } from 'react-hook-form';

import { useClearCustomError, useFieldCustomError, useIsFormFieldDisabled } from './hooks';
import type { CheckoutFormState } from './Checkout';

/** Пропсы, которые адаптер прокидывает в компонент */
type InjectedProps<TValue> = {
    /** Текущее значение поля */
    value: TValue;
    /** Обработчик ввода */
    onChange: (value: TValue) => void | Promise<void>;
    /** Обработчик потери фокуса */
    onBlur: () => void;
    /** Наличие ошибки на инпуте */
    error: boolean;
    /** Флаг задизейбленного состояния */
    disabled: boolean;
    /** Текст ошибки на инпуте */
    errorMessage?: string;
};

/** Поля, которые нужны, инпуту, и адаптеру */
export type BaseComponentProps = {
    /** Дата тег для тестов, прокидывается и в инпут */
    dataQaType?: string;
    /** Наличие ошибки на инпуте */
    error?: boolean;
    /** Имя инпута */
    name?: string;
    /** Флаг задизейбленного состояния */
    disabled?: boolean;
};

/** Поля, которые нужны только для работы адаптера */
type AdapterProps = {
    /** Имя поля для формы */
    name: Path<CheckoutFormState>;
    /** Правила валидации для поля */
    rules?: UseControllerProps['rules'];
    /** Нужно ли показывать валидационную ошибку на поле */
    hideError?: boolean;
    /** Определение стилей для контейнера в адаптере */
    adapterContainerClassName?: string;
};

type WithAdapterProps<T> = Omit<T, keyof AdapterProps> & AdapterProps;
type WithInjectedProps<T, TValue> = Omit<T, keyof InjectedProps<TValue>> & InjectedProps<TValue>;

type AdaptComponentProps<TProps, TValue> = Omit<TProps, 'onChange' | 'onBlur' | 'value'> & {
    /** Обработчик ввода */
    onChange?: InjectedProps<TValue>['onChange'];
    /** Обработчик потери фокуса */
    onBlur?: InjectedProps<TValue>['onBlur'];
};

/**
 * Декоратор, позволяющий интегрировать контролируемые поля с react-hook-form
 * @description
 * Добавляет интеграцию поля из кита с react-hook-form, также служит дополнительной абстракцией для упрощенного перехода на другие способы работы с формой
 *
 * Особенности:
 * 1. Не дает контролировать значение через value, единственный источник истины - react-hook-form
 * 2. Инпут должен принимать onChange, onBlur и value для корректной работы
 * 3. Инпут не прокидывает ref, что не позволяет управлять фокусом. При необходимости фокуса извне поле нужно добавить свою логику.
 */
export const createFormFieldAdapter =
    <TValue, TBaseProps extends BaseComponentProps = BaseComponentProps>(
        /** Базовый компонент, в него помимо собственных пропсов инжектятся пропсы адаптера */
        Component: ComponentType<WithInjectedProps<TBaseProps, TValue>>,
    ) =>
    /** Итоговый компонент, может принимать также поля для адаптера */
    (props: WithAdapterProps<AdaptComponentProps<TBaseProps, TValue>>) => {
        const { rules, hideError, adapterContainerClassName, name, ...inputProps } = props;
        const {
            fieldState: { error: libError },
            field: { value, onChange: libOnChange, onBlur: libOnBlur },
        } = useController({ name, rules });

        const clearError = useClearCustomError(name);

        const customError = useFieldCustomError(name);
        const disabled = useIsFormFieldDisabled(name);

        const hasError = Boolean(customError || libError || inputProps.error);

        const handleChange = (newValue: TValue) => {
            /** Очищаем ошибку при смене значения поля */
            if (customError) {
                clearError();
            }

            libOnChange(newValue);
            inputProps.onChange?.(newValue);
        };

        const handleBlur = () => {
            libOnBlur();
            inputProps.onBlur?.();
        };

        const errorMessage = customError?.message || libError?.message;

        const injectedProps: InjectedProps<TValue> = {
            onChange: handleChange,
            onBlur: handleBlur,
            value,
            error: hasError,
            errorMessage,
            disabled: disabled || Boolean(inputProps?.disabled),
        };

        const renderComponent = () => (
            <Component {...(inputProps as TBaseProps)} {...injectedProps} name={name as any} />
        );
        return (
            <div
                className={adapterContainerClassName}
                data-qa-type={inputProps.dataQaType && `${inputProps.dataQaType}.inputAdapter`}
            >
                {hideError ? (
                    renderComponent()
                ) : (
                    <FormRow error={!hideError && hasError} errorMessage={errorMessage} withoutOffset>
                        {renderComponent()}
                    </FormRow>
                )}
            </div>
        );
    };
